              "autosize": true,
              "blocks": [{
                "key": "6p1t0",
                "text": "Iako je marketinški vrlo primamljivo prikazivati cjelovečernje rituale s policama prepunih proizvoda, hrvatska manekenka Ljupka Gojić Mikić, poznata po svojoj prekrasnoj, njegovanoj koži lica, pokazala nam je da put do tog željenog, zaglađenog i blistavog tena, ne mora biti kompliciran.",
                "entityRanges": [],
