              "autosize": true,
              "blocks": [{
                "key": "avk",
                "text": "Idealno stanje kože je usko povezano s prirodnom sposobnošću optimalnog zadržavanja vode. Koža zasićena vodom ima glatku, na dodir meku površinu te optimalnu sposobnost ravnomjernog reflektiranja svjetlosti, otkrivajući blistav i prozračan sjaj iznutra. Upravo je to znanost iza glass skin trenda.  ",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "9b1us",
                "text": "‍",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "cnn21",
                "text": "Inovacija L’Oréal Paris povezuje visoke koncentracije aktivnih sastojaka zlatnog standarda s inovativnom tehnologijom FUSIOGLYDE™ koja omogućuje da se ovi hidratantni sastojci prenose sloj po sloj, bez osjećaja težine na koži. Rezultat je čista i blistava koža.  ",
                "entityRanges": [],
                "depth": 0
